// Valida token, formato del cuerpo y aplica filtros de entrada.
const j = $input.first().json;
const headers = j.headers || {};
const body = j.body || {};
const token = headers['x-chat-token'];
const bloquear = (status, respuesta, motivo) => [{ json: { bloqueo: motivo, http_status: status,
  cuerpo: { respuesta, intencion: 'fuera_de_tema', fuentes: [] } } }];

if (!token || token !== j.CHAT_TOKEN) return bloquear(401, 'No autorizado.', 'token');

const codigo = String(body.estudiante_codigo || '').trim().toUpperCase();
const sesion = String(body.session_id || '').trim();
const mensaje = String(body.mensaje || '').trim();
const accion = String(body.accion || 'chat').trim().toLowerCase();

// Acciones directas de la app: "perfil" (ficha del estudiante) y "noticias" (noticias del dia). No requieren mensaje.
if (accion === 'perfil' || accion === 'noticias') {
  if (!/^U00[0-9]{6}$/.test(codigo))
    return bloquear(400, 'Código de estudiante inválido: debe ser U00 seguido de 6 dígitos.', 'formato');
  return [{ json: { bloqueo: '', accion, estudiante_codigo: codigo, session_id: sesion,
    mcp_url: String(j.MCP_URL).replace(/\/+$/, '') } }];
}

if (!/^U00[0-9]{6}$/.test(codigo) || !sesion || sesion.length > 100 || !mensaje)
  return bloquear(400, 'Solicitud inválida: se requieren estudiante_codigo, session_id y mensaje.', 'formato');
if (mensaje.length > 1000)
  return bloquear(200, 'Tu mensaje es demasiado largo. Resúmelo en menos de 1000 caracteres.', 'longitud');

const m = mensaje.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');

const inyeccion = [
  /ignora (todas )?(las )?(instrucciones|reglas|indicaciones)/, /olvida (todo|tus instrucciones|las instrucciones)/,
  /ignore (all |any )?(previous|prior|above) (instructions|rules)/, /disregard (the |all )?(previous|above)/,
  /(muestra|revela|dime|imprime|repite).{0,30}(prompt|instrucciones) (del sistema|de sistema|internas|iniciales)/,
  /system prompt/, /prompt del sistema/, /jailbreak/, /\bdan mode\b/, /modo desarrollador/, /developer mode/,
  /(actua|comportate|finge|pretende) (como|que eres)/, /you are now/, /a partir de ahora (eres|seras|actuaras)/,
  /<\s*\/?\s*(system|assistant|instructions?)\s*>/, /\[\s*(system|inst)\s*\]/,
];
if (inyeccion.some(r => r.test(m)))
  return bloquear(200, 'No puedo atender esa solicitud. Puedo ayudarte con cursos, calendario académico, noticias y trámites de la UNAB.', 'inyeccion');

const credenciales = [
  /contrasena|contrasenas|password|clave (de|del) (acceso|correo|banner|campus|portal)/,
  /(token|api ?key|secreto)s? (de|del) (sistema|servidor|n8n|mcp)/, /variables de entorno/,
];
if (credenciales.some(r => r.test(m)))
  return bloquear(200, 'Por seguridad no puedo gestionar ni mostrar contraseñas, claves o credenciales. Para recuperarlas usa los canales oficiales de la UNAB.', 'credenciales');

const otros = (mensaje.toUpperCase().match(/U00[0-9]{6}/g) || []).filter(c => c !== codigo);
const ajenos = [/(notas?|calificaciones|matricula|historial|promedio) (de|del) (mi )?(compan|amig|otro|otra|estudiante|alumno|hermano|novi)/,
  /(datos|informacion) (personales )?(de|del) (otro|otra|un|una) (estudiante|alumno|compan)/];
if (otros.length || ajenos.some(r => r.test(m)))
  return bloquear(200, 'Solo puedo mostrarte información académica de tu propio código de estudiante.', 'datos_ajenos');

return [{ json: {
  bloqueo: '', accion: 'chat', estudiante_codigo: codigo, session_id: sesion, mensaje,
  memory_key: codigo + ':' + sesion,
  mcp_url: String(j.MCP_URL).replace(/\/+$/, ''), google_sheet_id: j.GOOGLE_SHEET_ID } }];

