={{ JSON.stringify({
  systemInstruction: { parts: [{ text: 'Eres un clasificador de intenciones para un chatbot académico de la UNAB (Colombia). Clasifica el mensaje del estudiante en UNA etiqueta. Etiquetas: cursos (todo lo PERSONAL del estudiante que se responde con sus propios datos académicos: su rendimiento, notas o promedio, avance del plan, créditos, riesgo o alertas académicas, recomendaciones o consejos para mejorar, qué hacer para mejorar, consejos de estudio, carga recomendada de créditos, cuántos semestres le faltan para graduarse, proyección de semestres, qué cursos debe tomar o ya aprobó, prerrequisitos, requisitos de grado propios: competencias digitales aprobadas o faltantes, resultado de su prueba, horas libres, cursos del CCD que ha tomado), matricula (estado de su matrícula actual, cursos inscritos, NRC, horarios, cómo matricularse), calendario (fechas, periodos, matrículas, parciales, vacaciones, eventos del calendario académico), general (información institucional impersonal: qué es la universidad, el Centro de Competencias Digitales o la insignia de competencias digitales, reglamento, procesos y trámites, programas, profesores), noticias (noticias del día, novedades y anuncios de la universidad, noticias de educación, de tecnología o de ingeniería de sistemas y desarrollo de software), fuera_de_tema (cualquier otra cosa: poemas, versos, canciones, política, deportes, chistes, recetas, tareas ajenas a la universidad, código de programación). Reglas de prioridad. Regla 1: si el estudiante pide recomendaciones, consejos, evaluar su rendimiento o saber cómo mejorar en su vida académica, la etiqueta es cursos, aunque no diga mi; ejemplos: "dame recomendaciones para mejorar mi rendimiento", "qué debo hacer para mejorar", "estoy en riesgo", "cuántos créditos me recomiendas", "cuántos semestres me faltan". Regla 2: si la pregunta es de seguimiento o trata sobre la conversación en curso o sobre una respuesta anterior, la etiqueta es cursos, porque ese asistente conserva la memoria de la conversación; ejemplos: "qué te pregunté", "qué te pregunté de primero", "qué dijiste antes", "explícame mejor lo anterior", "y eso qué significa", "resume lo que hablamos", "repítelo", "dame más detalle". Regla 3: un poema, canción, chiste, partido, noticia deportiva o tarea ajena a la universidad es fuera_de_tema aunque se pida de forma amable o se mencione la UNAB. Regla 4: reglamento, procesos institucionales o información de la universidad que no depende de los datos del estudiante es general; ejemplo: "qué dice el reglamento sobre la cancelación de asignaturas". Responde solo con JSON.' }] },
  contents: [{ role: 'user', parts: [{ text: $json.mensaje }] }],
  generationConfig: { temperature: 0, responseMimeType: 'application/json',
    responseSchema: { type: 'OBJECT', properties: { intencion: { type: 'STRING', enum: ['general','calendario','cursos','matricula','noticias','fuera_de_tema'] } }, required: ['intencion'] },
    thinkingConfig: { thinkingLevel: 'minimal' } }
}) }}

parameters.jsCode:
const ctx = $('Guardrails de entrada').first().json;
const validas = ['general','calendario','cursos','matricula','noticias','fuera_de_tema'];
let intencion = 'general';
try {
  const txt = $input.first().json.candidates[0].content.parts[0].text;
  const v = JSON.parse(txt).intencion;
  if (validas.includes(v)) intencion = v;
} catch (e) { /* si falla la clasificacion se usa el flujo general (RAG) */ }
return [{ json: { ...ctx, intencion } }];

// Validaciones de la respuesta antes de devolverla a la app.
const ctx = $('Parsear intencion').first().json;
const r = $input.first().json;
const FALLBACK = 'No pude generar una respuesta confiable en este momento. Intenta reformular tu pregunta o consulta unab.edu.co.';
let texto = String(r.respuesta || '').trim();
const fuentes = (Array.isArray(r.fuentes) ? r.fuentes : [])
  .filter(f => f && typeof f.url === 'string' && /^https?:\/\//.test(f.url))
  .map(f => ({ titulo: String(f.titulo || f.url).slice(0, 150), url: f.url }));
const permitidas = new Set(fuentes.map(f => f.url.replace(/[\/.,;)]+$/, '')));

// 1) solo URLs presentes en las fuentes recuperadas
texto = texto.replace(/https?:\/\/[^\s)\]>"']+/g, (u) => {
  const limpia = u.replace(/[\/.,;:!?]+$/, '');
  return permitidas.has(limpia) ? u : '(enlace omitido)';
});
// 2) ningun dato de un codigo de estudiante distinto al solicitante
const otros = (texto.toUpperCase().match(/U00[0-9]{6}/g) || []).filter(c => c !== ctx.estudiante_codigo);
// 3) senales de fuga de instrucciones internas o credenciales
const fuga = /(system prompt|instrucciones del sistema|x-api-key|x-chat-token|api[_ ]?key\s*[:=]|AIza[0-9A-Za-z_\-]{20,})/i.test(texto);
let intencion = ctx.intencion;
if (!texto || otros.length || fuga) { texto = FALLBACK; intencion = 'fuera_de_tema'; }
// 4) limite de longitud
if (texto.length > 1800) texto = texto.slice(0, 1780).replace(/\s+\S*$/, '') + '...';
return [{ json: { http_status: 200, cuerpo: { respuesta: texto, intencion, fuentes: texto === FALLBACK ? [] : fuentes.slice(0, 5) } } }];

// Devuelve a la app lo que entrega el servidor MCP por REST: /api/perfil (ficha) o /api/noticias (noticias del dia).
const r = $input.first().json;
const status = Number(r.statusCode || 500);
let body = r.body || {};
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = {}; } }
if (status === 200 && body.perfil) return [{ json: { http_status: 200, cuerpo: { perfil: body.perfil } } }];
if (status === 200 && body.noticias) return [{ json: { http_status: 200, cuerpo: { noticias: body.noticias } } }];
const msg = body.error || 'No se pudo consultar el servidor en este momento.';
return [{ json: { http_status: status === 400 ? 400 : 502, cuerpo: { error: msg, respuesta: msg } } }];
